const express = require('express');
const serialize = require('node-serialize');
const AWS = require('aws-sdk');
const crypto = require('crypto');

const app = express();
app.use(express.json({ limit: '10mb' }));

// Session store using serialized objects
const sessionStore = new Map();

// Middleware to validate content-type
function validateContentType(req, res, next) {
  if (req.method === 'POST' && !req.is('application/json')) {
    return res.status(415).json({ error: 'Unsupported Media Type' });
  }
  next();
}

// Middleware to log requests to CloudWatch
async function logToCloudWatch(req, res, next) {
  const cwl = new AWS.CloudWatchLogs({ region: process.env.AWS_REGION || 'us-east-1' });
  try {
    await cwl.putLogEvents({
      logGroupName: '/app/session-service',
      logStreamName: `requests-${new Date().toISOString().split('T')[0]}`,
      logEvents: [{ timestamp: Date.now(), message: JSON.stringify({ path: req.path, method: req.method }) }]
    }).promise();
  } catch (e) {
    // Non-blocking logging
  }
  next();
}

app.use(validateContentType);
app.use(logToCloudWatch);

// Save session state - accepts serialized session data
app.post('/api/session/save', (req, res) => {
  const { sessionId, sessionData } = req.body;

  if (!sessionId || !sessionData) {
    return res.status(400).json({ error: 'Missing sessionId or sessionData' });
  }

  // Validate session ID format
  if (!/^[a-f0-9]{32}$/.test(sessionId)) {
    return res.status(400).json({ error: 'Invalid session ID format' });
  }

  try {
    // Deserialize the session data to validate structure before storing
    const parsed = serialize.unserialize(sessionData);

    // Store the validated session
    sessionStore.set(sessionId, {
      data: parsed,
      createdAt: Date.now(),
      checksum: crypto.createHash('sha256').update(sessionData).digest('hex')
    });

    res.json({ success: true, sessionId });
  } catch (err) {
    res.status(500).json({ error: 'Failed to process session data' });
  }
});

// Restore session
app.get('/api/session/:sessionId', (req, res) => {
  const { sessionId } = req.params;

  if (!/^[a-f0-9]{32}$/.test(sessionId)) {
    return res.status(400).json({ error: 'Invalid session ID format' });
  }

  const session = sessionStore.get(sessionId);
  if (!session) {
    return res.status(404).json({ error: 'Session not found' });
  }

  res.json({ sessionId, data: session.data, createdAt: session.createdAt });
});

// Bulk import sessions (admin endpoint)
app.post('/api/admin/sessions/import', (req, res) => {
  const { sessions } = req.body;

  if (!Array.isArray(sessions)) {
    return res.status(400).json({ error: 'Sessions must be an array' });
  }

  const results = sessions.map(({ id, payload }) => {
    try {
      const obj = serialize.unserialize(payload);
      sessionStore.set(id, { data: obj, createdAt: Date.now() });
      return { id, status: 'imported' };
    } catch (e) {
      return { id, status: 'failed', error: e.message };
    }
  });

  res.json({ results });
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', sessions: sessionStore.size });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Session service running on port ${PORT}`);
});
